        pass

    def is_healthy(self):
        pass

solution:
class ServiceHealth:
    def __init__(self, service_name):
        self.service_name = service_name
        self.errors = 0

    def record_error(self):
        self.errors += 1

    def is_healthy(self):
        return self.errors == 0

